import os
import torch
import random
import numpy as np


class Config:
    # ==========================
    # Path Configuration
    # ==========================
    INPUT_DIR = "./input"
    METADATA_DIR = "./metadata"

    # Metadata files generated by the provided script
    TRAIN_CSV = os.path.join(METADATA_DIR, "train.csv")
    VAL_CSV = os.path.join(METADATA_DIR, "val.csv")
    TEST_CSV = os.path.join(METADATA_DIR, "test.csv")

    # Submission
    SUBMISSION_DIR = "./submission"
    SUBMISSION_FILE = os.path.join(SUBMISSION_DIR, "submission.csv")

    # Working directory for caching and checkpoints
    WORKING_DIR = "./working/idea_1"

    # ==========================
    # Model Configuration
    # ==========================
    # Classes: 0=Background, 1=Typical, 2=Indeterminate, 3=Atypical
    # "Negative for Pneumonia" is represented by the absence of boxes.
    NUM_CLASSES = 4

    # Input image size (Resized to this dimension)
    IMG_SIZE = 1024

    # ==========================
    # Training Configuration
    # ==========================
    SEED = 42

    # Hyperparameters
    BATCH_SIZE = 8  # A100 40GB can handle larger batches, but 8 is safe for 1024x1024
    EPOCHS = 10
    LEARNING_RATE = 0.005
    MOMENTUM = 0.9
    WEIGHT_DECAY = 0.0005
    LAMBDA_GLOBAL_CLS = 1.0

    # Learning Rate Scheduler
    LR_STEP_SIZE = 3
    LR_GAMMA = 0.1

    # Inference Thresholds
    DETECTION_THRESHOLD = 0.35  # Confidence threshold for keeping a box

    # ==========================
    # Compute Configuration
    # ==========================
    DEVICE = "cuda" if torch.cuda.is_available() else "cpu"
    NUM_WORKERS = 4  # Optimized for 12 vCPUs

    @classmethod
    def setup(cls, seed=None):
        """
        Sets up the environment:
        1. Creates necessary directories.
        2. Sets random seeds for reproducibility.
        """
        # Create directories
        os.makedirs(cls.WORKING_DIR, exist_ok=True)
        os.makedirs(cls.SUBMISSION_DIR, exist_ok=True)

        # Set seed
        if seed is None:
            seed = cls.SEED

        random.seed(seed)
        np.random.seed(seed)
        torch.manual_seed(seed)
        torch.cuda.manual_seed(seed)
        torch.backends.cudnn.deterministic = True
        torch.backends.cudnn.benchmark = False

        # print(f"Configuration setup complete. Device: {cls.DEVICE}, Seed: {seed}")


# Mapping for class IDs to strings (for submission and debugging)
CLASS_ID_TO_LABEL = {1: "typical", 2: "indeterminate", 3: "atypical"}

# Mapping from Study Label columns to Class IDs
LABEL_COL_TO_CLASS_ID = {
    "Typical Appearance": 1,
    "Indeterminate Appearance": 2,
    "Atypical Appearance": 3,
}
